  List<AiTool> searchTools(String query) {
    if (query.isEmpty) return getTools();
    final q = query.toLowerCase();
    return getTools().where((t) =>
        t.name.toLowerCase().contains(q) ||
        t.description.toLowerCase().contains(q) ||
        t.company.toLowerCase().contains(q) ||
        t.tagline.toLowerCase().contains(q)).toList();
  }

  List<AiTool> getToolsByCategory(AiToolCategory category) =>
      getTools().where((t) => t.category == category).toList();

  List<AiTool> getToolsByPricing(PricingTier tier) =>
      getTools().where((t) => t.pricing == tier).toList();

  List<AiTool> getTrendingTools() =>
      getTools().where((t) => t.isTrending).toList();

  List<AiTool> getNewTools() =>
      getTools().where((t) => t.isNew).toList();
}
